create function pg_temp.eng_cmd(a text,d jsonb) returns jsonb language sql as $$select public.product_command(a,d,gen_random_uuid())$$;
grant execute on function pg_temp.eng_cmd(text,jsonb) to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.eng_cmd('engagement.reward_rule.create','{"branch_id":"e2000000-0000-4000-8000-000000000001","code":"attendance_badge","title":"Attendance badge","description":"One noncash academy badge after review","source_kind":"challenge","unit":"badge","quantity":1}')$$,'Owner creates transparent noncash rule');
select set_config('test.reward',(select id::text from public.engagement_reward_rules where code='attendance_badge'),true);
select lives_ok($$select pg_temp.eng_cmd('engagement.reward_rule.publish',jsonb_build_object('id',current_setting('test.reward')))$$,'Owner publishes rule');
select lives_ok($$select pg_temp.eng_cmd('engagement.challenge.create',jsonb_build_object('branch_id','e2000000-0000-4000-8000-000000000001','sport','swimming','title','Attendance challenge','description','Attend one finalized session','starts_at',now()-interval '1 day','ends_at',now()+interval '7 days','reward_policy_id',current_setting('test.reward'),'rule','{"kind":"attendance","count":1}'::jsonb))$$,'Owner creates attendance challenge');
