select is((select count(*)::int from public.engagement_challenges where id=current_setting('test.challenge')::uuid),0,'Challenge drafts hidden from families');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.eng_cmd('engagement.challenge.publish',jsonb_build_object('id',current_setting('test.challenge')))$$,'Owner publishes challenge');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.eng_cmd('engagement.challenge.join',jsonb_build_object('challenge_id',current_setting('test.challenge'),'child_id','e3000000-0000-4000-8000-000000000002'))$$,'Own family enrolls eligible athlete');
select set_config('test.entry',(select id::text from public.engagement_entries where child_id='e3000000-0000-4000-8000-000000000002'),true);
select lives_ok($$select pg_temp.eng_cmd('engagement.challenge.join',jsonb_build_object('challenge_id',current_setting('test.challenge'),'child_id','e3000000-0000-4000-8000-000000000002'))$$,'Repeated challenge enrollment is idempotent');
select is((select count(*)::int from public.engagement_entries where challenge_id=current_setting('test.challenge')::uuid),1,'No duplicate entries');
select lives_ok($$select pg_temp.eng_cmd('engagement.completion.submit',jsonb_build_object('entry_id',current_setting('test.entry')))$$,'Completion uses actual finalized attendance');
select is((select count(*)::int from public.engagement_completions),0,'Internal completion draft hidden from family');
