select throws_ok($$select pg_temp.eng_cmd('engagement.completion.submit',jsonb_build_object('entry_id',current_setting('test.entry')))$$,'42501',null,'Unrelated family cannot claim completion');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
