select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select set_config('test.completion',(select id::text from public.engagement_completions where entry_id=current_setting('test.entry')::uuid),true);
select throws_ok($$select pg_temp.eng_cmd('engagement.reward.grant',jsonb_build_object('source_kind','challenge','source_id',current_setting('test.completion'),'reason','Award reviewed badge'))$$,'P0409',null,'Grant cannot bypass qualification review');
select lives_ok($$select pg_temp.eng_cmd('engagement.completion.review',jsonb_build_object('id',current_setting('test.completion'),'decision','approved','reason','Verified session evidence'))$$,'Independent authorized reviewer approves completion');
select lives_ok($$select pg_temp.eng_cmd('engagement.reward.grant',jsonb_build_object('source_kind','challenge','source_id',current_setting('test.completion'),'reason','Award reviewed badge'))$$,'Reviewed completion issues noncash ledger grant');
select set_config('test.grant',(select id::text from public.engagement_reward_ledger where kind='grant' and completion_id=current_setting('test.completion')::uuid),true);
select lives_ok($$select pg_temp.eng_cmd('engagement.reward.grant',jsonb_build_object('source_kind','challenge','source_id',current_setting('test.completion'),'reason','Retry award'))$$,'Duplicate grant returns original');
