select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select pg_temp.eng_cmd('engagement.reward.reverse',jsonb_build_object('id',current_setting('test.grant'),'reason','Award corrected after review'))$$,'Reward reversal appends compensating entry');
select is((select sum(delta)::int from public.engagement_reward_ledger where child_id='e3000000-0000-4000-8000-000000000002'),0,'Grant and reversal reconcile');
select lives_ok($$select pg_temp.eng_cmd('engagement.reward.reverse',jsonb_build_object('id',current_setting('test.grant'),'reason','Retry reversal'))$$,'Duplicate reversal is idempotent');
