select throws_ok($$select pg_temp.eng_cmd('engagement.referral.redeem',jsonb_build_object('family_id','e3000000-0000-4000-8000-000000000001','code',current_setting('test.code')))$$,'P0409',null,'Self-referral denied');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.eng_cmd('engagement.referral.redeem',jsonb_build_object('family_id','e3000000-0000-4000-8000-000000000004','code',current_setting('test.code')))$$,'Other family records referral before membership');
select lives_ok($$select pg_temp.eng_cmd('engagement.referral.redeem',jsonb_build_object('family_id','e3000000-0000-4000-8000-000000000004','code',current_setting('test.code')))$$,'Repeated referral code entry returns original claim');
select is((select count(*)::int from public.engagement_referral_claims),0,'Family cannot read internal referral qualification');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select set_config('test.referral',(select id::text from public.engagement_referral_claims where referred_family_id='e3000000-0000-4000-8000-000000000004'),true);
select is((select count(*)::int from public.engagement_referral_claims where referred_family_id='e3000000-0000-4000-8000-000000000004'),1,'Repeated redemption cannot create multiple referral claims');
select throws_ok($$select pg_temp.eng_cmd('engagement.referral.review',jsonb_build_object('id',current_setting('test.referral'),'decision','approved','reason','Attempt without payment'))$$,'P0409',null,'Referral approval requires genuine first paid membership evidence');
reset role;
insert into public.branch_sports values('e2000000-0000-4000-8000-000000000001','swimming');
insert into public.children(id,family_id,name,reported_age,age_captured_on) values('e3000000-0000-4000-8000-000000000005','e3000000-0000-4000-8000-000000000004','Referred athlete',7,current_date);
insert into public.child_sports(child_id,sport,level_id) values('e3000000-0000-4000-8000-000000000005','swimming','e2000000-0000-4000-8000-000000000003');
