select pg_temp.eng_cmd('commercial.package.create','{"branch_id":"e2000000-0000-4000-8000-000000000001","sport":"swimming","name":"Referral test package","price_minor":10000,"session_allowance":4,"terms":"Explicit synthetic terms"}');
select pg_temp.eng_cmd('commercial.membership.start',jsonb_build_object('child_id','e3000000-0000-4000-8000-000000000005','package_id',(select id from public.commercial_packages where name='Referral test package'),'starts_on',current_date,'accepted',true));
