select pg_temp.eng_cmd('commercial.payment.record',jsonb_build_object('family_id','e3000000-0000-4000-8000-000000000004','branch_id','e2000000-0000-4000-8000-000000000001','invoice_id',current_setting('test.invoice'),'amount_minor',5000,'method','cash','reference','ENG-PARTIAL-1'));
select throws_ok($$select pg_temp.eng_cmd('engagement.referral.review',jsonb_build_object('id',current_setting('test.referral'),'decision','approved','reason','Only half paid'))$$,'P0409',null,'Partial payment does not qualify referral');
select pg_temp.eng_cmd('commercial.payment.record',jsonb_build_object('family_id','e3000000-0000-4000-8000-000000000004','branch_id','e2000000-0000-4000-8000-000000000001','invoice_id',current_setting('test.invoice'),'amount_minor',5000,'method','cash','reference','ENG-FULL-2'));
select lives_ok($$select pg_temp.eng_cmd('engagement.referral.review',jsonb_build_object('id',current_setting('test.referral'),'decision','approved','reason','First membership fully paid'))$$,'Full actual allocation qualifies referral');
select lives_ok($$select pg_temp.eng_cmd('engagement.reward.grant',jsonb_build_object('source_kind','referral','source_id',current_setting('test.referral'),'reason','Qualified family referral reward'))$$,'Qualified referral grants only noncash reward');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select sum(delta)::int from public.engagement_reward_ledger where family_id='e3000000-0000-4000-8000-000000000001' and unit='star'),5,'Referrer sees earned reward');
