select pg_temp.eng_cmd('development.criteria.create','{"sport":"swimming","level_id":"e2000000-0000-4000-8000-000000000003","title":"Engagement distance","criteria":[{"key":"distance","label":"Distance","unit":"m","min":0,"max":100,"direction":"higher"}]}');
select set_config('test.criteria',(select id::text from public.development_criteria where title='Engagement distance'),true);
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select pg_temp.eng_cmd('development.assessment.save',jsonb_build_object('session_id','e2000000-0000-4000-8000-000000000007','child_id','e3000000-0000-4000-8000-000000000002','criteria_id',current_setting('test.criteria'),'scores','{"distance":25}'::jsonb,'summary','Measured swim distance'));
select set_config('test.assessment',(select id::text from public.development_assessments where child_id='e3000000-0000-4000-8000-000000000002'),true);
select pg_temp.eng_cmd('development.assessment.submit',jsonb_build_object('id',current_setting('test.assessment')));
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select pg_temp.eng_cmd('development.assessment.review',jsonb_build_object('id',current_setting('test.assessment'),'decision','approved','reason','Checked measured value'));
select pg_temp.eng_cmd('development.assessment.publish',jsonb_build_object('id',current_setting('test.assessment')));
select throws_ok($$select pg_temp.eng_cmd('engagement.challenge.create',jsonb_build_object('branch_id','e2000000-0000-4000-8000-000000000001','sport','swimming','title','Invalid metric target','description','Must match criteria range','starts_at',now()-interval '1 day','ends_at',now()+interval '7 days','reward_policy_id',current_setting('test.reward'),'rule',jsonb_build_object('kind','metric','criteria_id',current_setting('test.criteria'),'metric_key','distance','target',101)))$$,'22023',null,'Metric challenge validates target against exact criteria range');
select lives_ok($$select pg_temp.eng_cmd('engagement.challenge.create',jsonb_build_object('branch_id','e2000000-0000-4000-8000-000000000001','sport','swimming','title','Distance challenge','description','Swim at least twenty metres with reviewed evidence','starts_at',now()-interval '1 day','ends_at',now()+interval '7 days','reward_policy_id',current_setting('test.reward'),'rule',jsonb_build_object('kind','metric','criteria_id',current_setting('test.criteria'),'metric_key','distance','target',20)))$$,'Metric challenge retains configured unit and direction');
select set_config('test.metric_challenge',(select id::text from public.engagement_challenges where title='Distance challenge'),true);
select pg_temp.eng_cmd('engagement.challenge.publish',jsonb_build_object('id',current_setting('test.metric_challenge')));
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select pg_temp.eng_cmd('engagement.challenge.join',jsonb_build_object('challenge_id',current_setting('test.metric_challenge'),'child_id','e3000000-0000-4000-8000-000000000002'));
select lives_ok($$select pg_temp.eng_cmd('engagement.completion.submit',jsonb_build_object('entry_id',(select id from public.engagement_entries where challenge_id=current_setting('test.metric_challenge')::uuid)))$$,'Metric completion validates published measured result');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select pg_temp.eng_cmd('engagement.report.generate',jsonb_build_object('session_id','e2000000-0000-4000-8000-000000000007','child_id','e3000000-0000-4000-8000-000000000002','month',to_char((now()-interval '2 hours') at time zone 'Asia/Dubai','YYYY-MM')))$$,'Coach generates factual monthly report draft');
select ok((select summary like '%25 m%' and summary like '%1 published assessments%' from public.development_reports where child_id='e3000000-0000-4000-8000-000000000002'),'Generated draft contains true counts and original units');
select set_config('test.report',(select id::text from public.development_reports where child_id='e3000000-0000-4000-8000-000000000002'),true);
select lives_ok($$select pg_temp.eng_cmd('engagement.report.edit',jsonb_build_object('id',current_setting('test.report'),'summary','Reviewed factual draft: 25 m best distance.'))$$,'Coach can edit generated draft before submission');
select pg_temp.eng_cmd('development.report.submit',jsonb_build_object('id',current_setting('test.report')));
select throws_ok($$select pg_temp.eng_cmd('engagement.report.edit',jsonb_build_object('id',current_setting('test.report'),'summary','Cannot alter submitted draft'))$$,'P0409',null,'Submitted report is locked during review');
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.development_reports where child_id='e3000000-0000-4000-8000-000000000002'),0,'Generated report remains private until normal review and publication');
reset role;
delete from public.branch_permissions where user_id='e1000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.engagement_completions),0,'Coach revocation removes engagement evidence access immediately');
select is((select count(*)::int from public.engagement_entries),0,'Coach revocation removes athlete challenge entry access');
reset role;
select throws_ok($$update public.engagement_reward_ledger set delta=20 where id=current_setting('test.grant')::uuid$$,'42501',null,'Reward ledger append-only');
select throws_ok($$update public.engagement_challenges set rule='{"kind":"attendance","count":0}' where id=current_setting('test.challenge')::uuid$$,'42501',null,'Published challenge rules cannot change');
select * from finish();rollback;
